function EditContractDocuments({contract,data,reload,persona}:{contract:any,data:any,reload:()=>void,persona:string}){useLang();
 const [uploading,setUploading]=useState(false),[err,setErr]=useState('');
 const suffix=persona==='owner'?'':'?persona='+encodeURIComponent(persona);
 async function openDoc(id:string){try{const r=await authorizedFetch('/api/contract-document?contract='+encodeURIComponent(contract.id)+'&id='+encodeURIComponent(id)+(persona==='owner'?'':'&persona='+encodeURIComponent(persona)));const d=await r.json();if(!r.ok)throw new Error(d.error);window.open(d.url,'_blank','noopener,noreferrer')}catch(e){setErr((e as Error).message)}}
 return <div className="evidence-panel"><h3>{tx("Contract documents")}</h3>{!(contract.documents||[]).length&&<p className="muted">{tx("No documents uploaded.")}</p>}{(contract.documents||[]).map((d:any)=><div className="evidence-row" key={d.id}><button className="text-button" onClick={()=>openDoc(d.id)}>{tx(d.name)}</button><small>{tx("{0} KB", [tx((d.bytes/1024).toFixed(0))])}</small></div>)}<form className="form" onSubmit={async e=>{e.preventDefault();const form=e.currentTarget;setErr('');setUploading(true);try{const body=new FormData(form);body.set('contract',contract.id);body.set('revision',String(data.revision));const r=await authorizedFetch('/api/contract-document'+suffix,{method:'POST',body});const d=await r.json();if(!r.ok)throw new Error(d.error);form.reset();await reload()}catch(e){setErr((e as Error).message)}finally{setUploading(false)}}}><label>{tx("Upload document (contract PDF, addendum, etc.)")}<input type="file" name="file" required/></label><button className="secondary" disabled={uploading}>{tx(uploading?'Uploading…':'Upload document')}</button></form>{err&&<p role="alert" className="access-error">{tx(err)}</p>}</div>;
}
